custom.scss:
body {
    line-height: normal;
}

.button--primary {
    color: stencilColor("button--primary-color");
    &:hover, &:focus, &:active {
        color: stencilColor("button--primary-color");
    }
    @media (min-width: 1025px) {
        &:hover, &:focus, &:active {
            color: stencilColor("button--primary-colorHover");
        }
    }
}

.mCSB_scrollTools .mCSB_dragger .mCSB_dragger_bar {
	background-color: #6e6e6e;
}


.card-title {
    height: 55px;
    line-height: 18px;
}

.productRelated {
    display: none !important;
}

.productView-description {
    width:100% !important;
}

header.header {
background-color:rgba(255,255,255,0.85) !important;
backdrop-filter:saturate(.5) blur(7px) !important;
-webkit-backdrop-filter:saturate(.5) blur(7px) !important;
}
.themevale_header-middle {
background-color:transparent !important;
}


///Custom Info Card

div.hidden {
  display: none;
  padding:.5em;
  background-color:rgba(255,255,255,.4);
  border-radius:.25em;
  -webkit-box-shadow: 5px 5px 5px -4px #AAAAAA; 
  box-shadow: 5px 5px 5px -4px #AAAAAA;
  backdrop-filter:saturate(.9) blur(3px)!important;
  position: absolute;
  bottom: 3.75em;
  left:3.25em;
  min-width:325px;
  border:1px solid gray;
}
svg.infoHover:hover circle.cls-2{
    filter:brightness(50%);
}

a.infoTextA:hover + div.hidden {
    display: block;
}
div.hidden {
  max-width:20%;
}
.infoHover {
  height:50px;
  position:relative;
}
p.infoText {
  margin:0 !important;
}
div.parentDiv {
    position:relative;
}
.themevale_search-custom .form-field {
    @media (min-width: 801px) {
        background-color:#ffffffc4 !important;
    }
    @media (max-width: 800px) {
        background-color:white;
    }
}
.form-input {
    background-color:transparent !important;
}
button.btn-search:hover {
    background-color:#880505 !important;
}
.themevale_search-custom .btn-search {
    transition:background-color .25s ease-out !important;
}

footer .themevale_middleFooter .form-input {
  background-color:white !important;
}
.shipping-estimator .shipping-quotes {
    clear:both!important;
}

#sticky_addtocart {
	box-shadow:none !important;
	background:transparent !important;
}
#sticky_addtocart .container {
	border-radius:20px;
	background:#ffffffcc;
	backdrop-filter:blur(20px);
}

.themevale_header-layout-1.is-sticky .themevale_header-middle .item--hamburger+.logo-wrapper {
    margin-left: 20px !important;
}

.show_sticky .container .item .product-wrapper .product-image img {
	padding:5px;
	border-radius:20px;
}

*::selection {
    background-color: #ea5757;
    color: white;
}
*::-moz-selection {
    background-color: #ea5757;
    color: white;
}
